{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled for the S3 bucket, which can lead to data loss or inability to recover previous versions of objects."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for the S3 bucket, making it difficult to track and monitor access to the bucket."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured to use KMS encryption by default, potentially leaving the stored data unencrypted."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured, which could allow unauthorized public access to the bucket."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs_versioning" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs_encryption" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail_logs_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_kms_key" "cloudtrail_logs_kms_key" {
  description             = "KMS key for CloudTrail logs"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs_public_access_block" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "cloudtrail_logs_logging" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  target_bucket = aws_s3_bucket.cloudtrail_logs.id
  target_prefix = "logs/"
}",
  "fix_summary": "Enabled versioning, server-side encryption with KMS, public access block, and access logging for the S3 bucket storing CloudTrail logs."
}
